mapper.select:
select question_id, title, category, reward_points, frozen_points, status, best_answer_id, ask_user_id, ask_nick_name, ask_avatar, ask_dept_name, visibility_scope, expiry_time, close_time, view_count, answer_count, audit_status, tags, create_time, update_time from bbs_qa_question
del_flag = '0' and audit_status = 'approved'
and status = #{status}
and category = #{category}
and (title like concat('%', #{keyword}, '%') or tags like concat('%', #{keyword}, '%'))
order by reward_points desc, create_time desc order by view_count desc, create_time desc order by answer_count desc, create_time desc order by create_time desc

mapper.update:
update bbs_qa_question
set status = 'archived', archive_time = now(), update_time = now()
where question_id = #{questionId}

update bbs_qa_question
set status = 'cancelled', close_time = now(), update_time = now()
where question_id = #{questionId}

update bbs_qa_question
set view_count = view_count + 1, update_time = now()
where question_id = #{questionId}

update bbs_qa_question
set answer_count = answer_count + 1, update_time = now()
where question_id = #{questionId}

update bbs_qa_answer
set like_count = like_count + 1, update_time = now()
where answer_id = #{answerId}

update bbs_qa_answer
set like_count = greatest(like_count - 1, 0), update_time = now()
where answer_id = #{answerId}
